-- GenAI Dependence survey — Supabase schema (form version 2.8)
-- GENERATED by scripts/generate.mjs from public/questions.js. Do not edit by hand.
-- Run once in Supabase: Dashboard → SQL Editor → paste → Run.

create table if not exists public.responses (
  id             bigint generated always as identity primary key,
  submission_id  uuid not null unique,
  created_at     timestamptz not null default now(),
  started_at     timestamptz,
  duration_sec   integer,
  form_version   text not null,
  ui_lang        text,
  attention_pass boolean,
  -- data-authenticity fields (no personal data)
  respondent_id  uuid,                 -- random ID kept in the participant's browser (same device = same ID)
  ip_hash        text,                 -- one-way salted SHA-256 of the IP address; the IP itself is never stored
  device_type    text check (device_type in ('mobile', 'tablet', 'desktop', 'unknown')),
  src            text check (src ~ '^[a-z0-9_-]{1,60}$'),   -- recruitment source tag from the shared link
  receipt_code   text not null unique, -- shown to the participant; used for withdrawal requests
  bot_check      text check (bot_check in ('passed', 'not_configured')),
  dem1 smallint not null check (dem1 between 1 and 4),
  dem2 smallint not null check (dem2 between 1 and 2),
  dem3 text not null check (char_length(dem3) between 2 and 150),
  dem4 smallint not null check (dem4 between 1 and 3),
  dem5 text not null check (char_length(dem5) between 2 and 150),
  dem6 smallint not null check (dem6 between 1 and 10),
  dem6_other text check (char_length(dem6_other) <= 200),
  dem7 smallint not null check (dem7 between 1 and 4),
  dem8 smallint check (dem8 between 1 and 4),
  dem9 smallint not null check (dem9 between 1 and 4),
  dem10 smallint not null check (dem10 between 1 and 5),
  use1 text[] not null,
  use1_other text check (char_length(use1_other) <= 200),
  use2 smallint not null check (use2 between 1 and 4),
  use3 smallint not null check (use3 between 1 and 5),
  use4 smallint not null check (use4 between 1 and 5),
  use5 text[] not null,
  use5_other text check (char_length(use5_other) <= 200),
  use6 smallint not null check (use6 between 1 and 4),
  use8 smallint not null check (use8 between 1 and 3),
  use9 smallint not null check (use9 between 1 and 5),
  use10 text[] not null,
  use10_other text check (char_length(use10_other) <= 200),
  ct1 smallint not null check (ct1 between 1 and 5),
  ct2 smallint not null check (ct2 between 1 and 5),
  ct3 smallint not null check (ct3 between 1 and 5),
  ct4 smallint not null check (ct4 between 1 and 5),
  att smallint not null check (att between 1 and 5),
  ct5 smallint not null check (ct5 between 1 and 5),
  ct6 smallint not null check (ct6 between 1 and 5),
  ct8 smallint not null check (ct8 between 1 and 5),
  ct9 smallint not null check (ct9 between 1 and 5),
  sc1 smallint check (sc1 between 1 and 5),
  sc2 smallint check (sc2 between 1 and 5),
  sc3 smallint not null check (sc3 between 1 and 5),
  sc4 smallint not null check (sc4 between 1 and 5),
  sc5 smallint check (sc5 between 1 and 5),
  sc6 smallint check (sc6 between 1 and 5),
  sc7 smallint not null check (sc7 between 1 and 5),
  sc8 smallint not null check (sc8 between 1 and 5),
  sc9 smallint not null check (sc9 between 1 and 5),
  hc1 smallint not null check (hc1 between 1 and 5),
  hc2 smallint not null check (hc2 between 1 and 5),
  hc3 smallint not null check (hc3 between 1 and 5),
  hc4 smallint not null check (hc4 between 1 and 5),
  hc5 smallint not null check (hc5 between 1 and 5),
  hc6 smallint check (hc6 between 1 and 5),
  ase1 smallint not null check (ase1 between 1 and 5),
  ase2 smallint not null check (ase2 between 1 and 5),
  ase3 smallint not null check (ase3 between 1 and 5),
  ase4 smallint not null check (ase4 between 1 and 5),
  gse1 smallint not null check (gse1 between 1 and 5),
  gse2 smallint not null check (gse2 between 1 and 5),
  att2 smallint not null check (att2 between 1 and 5),
  gse3 smallint not null check (gse3 between 1 and 5),
  gse4 smallint not null check (gse4 between 1 and 5),
  gd1 smallint not null check (gd1 between 1 and 5),
  gd2 smallint not null check (gd2 between 1 and 5),
  gd3 smallint not null check (gd3 between 1 and 5),
  gd4 smallint not null check (gd4 between 1 and 5),
  gd5 smallint not null check (gd5 between 1 and 5),
  gd6 smallint not null check (gd6 between 1 and 5),
  gd8 smallint not null check (gd8 between 1 and 5),
  co1 smallint not null check (co1 between 1 and 5),
  co2 smallint not null check (co2 between 1 and 5),
  co3 smallint not null check (co3 between 1 and 5),
  co4 smallint not null check (co4 between 1 and 5),
  co5 smallint not null check (co5 between 1 and 5),
  co6 smallint not null check (co6 between 1 and 5),
  al1 smallint not null check (al1 between 1 and 5),
  al2 smallint not null check (al2 between 1 and 5),
  al3 smallint not null check (al3 between 1 and 5),
  al4 smallint not null check (al4 between 1 and 5),
  al5 smallint not null check (al5 between 1 and 5),
  al6 smallint not null check (al6 between 1 and 5),
  al7 smallint not null check (al7 between 1 and 5),
  al8 smallint not null check (al8 between 1 and 5),
  al9 smallint not null check (al9 between 1 and 5)
);

-- Only the server (service-role key, used by /api/submit) can read or write.
-- RLS on + no policies = the public anon key has no access at all.
alter table public.responses enable row level security;
revoke all on public.responses from anon, authenticated;
revoke all on public.responses from service_role;
grant select, insert on public.responses to service_role;   -- the form's server may only add rows (and read for the health check)

-- Append-only: once saved, a response can never be edited or deleted (not even by the researcher).
-- Removing this protection would require a new migration, which Supabase records in its history.
create or replace function public.responses_block_changes()
returns trigger language plpgsql set search_path = '' as $$
begin
  raise exception 'responses are append-only: % is not allowed', tg_op;
end;
$$;
drop trigger if exists responses_no_update_delete on public.responses;
create trigger responses_no_update_delete before update or delete on public.responses
  for each row execute function public.responses_block_changes();
drop trigger if exists responses_no_truncate on public.responses;
create trigger responses_no_truncate before truncate on public.responses
  for each statement execute function public.responses_block_changes();

-- Withdrawals are recorded here instead of deleting data; exclude them in analysis (view column "withdrawn").
create table if not exists public.withdrawals (
  id            bigint generated always as identity primary key,
  receipt_code  text not null unique,
  requested_at  timestamptz not null default now(),
  note          text
);
alter table public.withdrawals enable row level security;
revoke all on public.withdrawals from anon, authenticated;
revoke all on public.withdrawals from service_role;
grant select on public.withdrawals to service_role;   -- read-only, so the admin dashboard can mark withdrawn cases; adding withdrawals stays researcher-only (SQL Editor)

-- Link visits for the admin dashboard: anonymous events from the form page (no answers, no IP).
-- visitor_id = the same random browser ID as responses.respondent_id; one row per visitor, event and day.
create table if not exists public.visits (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  day         date not null default ((now() at time zone 'Asia/Dhaka')::date),   -- Bangladesh date
  visitor_id  uuid not null,
  event       text not null check (event in ('view', 'start', 'screened_out')),
  src         text check (src ~ '^[a-z0-9_-]{1,60}$'),
  device_type text check (device_type in ('mobile', 'tablet', 'desktop', 'unknown')),
  unique (visitor_id, event, day)
);
comment on table public.visits is 'Form link visits: view = opened the form, start = gave a first answer, screened_out = answered No to an eligibility question';
alter table public.visits enable row level security;
revoke all on public.visits from anon, authenticated;
revoke all on public.visits from service_role;
grant select, insert on public.visits to service_role;   -- /api/visit adds events; /api/admin reads them

