-- Analysis-ready view: multi-select answers expanded to 0/1 columns,
-- reverse-coded items added as *_r, and construct mean scores.
create or replace view public.responses_spss
with (security_invoker = true) as
select
  id,
  created_at,
  started_at,
  duration_sec,
  form_version,
  ui_lang,
  attention_pass,
  respondent_id,
  ip_hash,
  device_type,
  src,
  receipt_code,
  bot_check,
  exists (select 1 from public.withdrawals w where w.receipt_code = responses.receipt_code) as withdrawn,
  dem1,
  dem2,
  dem3,
  dem4,
  dem5,
  dem6,
  dem6_other,
  dem7,
  dem8,
  dem9,
  dem10,
  (case when 'chatgpt' = any(use1) then 1 else 0 end) as use1_chatgpt,
  (case when 'gemini' = any(use1) then 1 else 0 end) as use1_gemini,
  (case when 'copilot' = any(use1) then 1 else 0 end) as use1_copilot,
  (case when 'meta_ai' = any(use1) then 1 else 0 end) as use1_meta_ai,
  (case when 'claude' = any(use1) then 1 else 0 end) as use1_claude,
  (case when 'deepseek' = any(use1) then 1 else 0 end) as use1_deepseek,
  (case when 'perplexity' = any(use1) then 1 else 0 end) as use1_perplexity,
  (case when 'github_copilot' = any(use1) then 1 else 0 end) as use1_github_copilot,
  (case when 'grammarly_quillbot' = any(use1) then 1 else 0 end) as use1_grammarly_quillbot,
  (case when 'other' = any(use1) then 1 else 0 end) as use1_other_selected,
  use1_other,
  use2,
  use3,
  use4,
  (case when 'concepts' = any(use5) then 1 else 0 end) as use5_concepts,
  (case when 'writing' = any(use5) then 1 else 0 end) as use5_writing,
  (case when 'coding' = any(use5) then 1 else 0 end) as use5_coding,
  (case when 'maths' = any(use5) then 1 else 0 end) as use5_maths,
  (case when 'summarising' = any(use5) then 1 else 0 end) as use5_summarising,
  (case when 'exam_prep' = any(use5) then 1 else 0 end) as use5_exam_prep,
  (case when 'ideas' = any(use5) then 1 else 0 end) as use5_ideas,
  (case when 'feedback' = any(use5) then 1 else 0 end) as use5_feedback,
  (case when 'translation' = any(use5) then 1 else 0 end) as use5_translation,
  (case when 'research_sources' = any(use5) then 1 else 0 end) as use5_research_sources,
  (case when 'other' = any(use5) then 1 else 0 end) as use5_other_selected,
  use5_other,
  use6,
  use8,
  use9,
  (case when 'info' = any(use10) then 1 else 0 end) as use10_info,
  (case when 'messages' = any(use10) then 1 else 0 end) as use10_messages,
  (case when 'entertainment' = any(use10) then 1 else 0 end) as use10_entertainment,
  (case when 'advice' = any(use10) then 1 else 0 end) as use10_advice,
  (case when 'planning' = any(use10) then 1 else 0 end) as use10_planning,
  (case when 'skills' = any(use10) then 1 else 0 end) as use10_skills,
  (case when 'work' = any(use10) then 1 else 0 end) as use10_work,
  (case when 'none' = any(use10) then 1 else 0 end) as use10_none,
  (case when 'other' = any(use10) then 1 else 0 end) as use10_other_selected,
  use10_other,
  ct1,
  ct2,
  ct3,
  ct4,
  att,
  ct5,
  ct6,
  ct8,
  ct9,
  sc1,
  sc2,
  sc3,
  sc4,
  sc5,
  sc6,
  sc7,
  sc8,
  sc9,
  hc1,
  hc2,
  hc3,
  hc4,
  hc5,
  hc6,
  (6 - hc6) as hc6_r,
  ase1,
  ase2,
  ase3,
  ase4,
  gse1,
  gse2,
  att2,
  gse3,
  gse4,
  gd1,
  gd2,
  gd3,
  gd4,
  gd5,
  gd6,
  gd8,
  co1,
  co2,
  co3,
  co4,
  co5,
  co6,
  al1,
  al2,
  al3,
  al4,
  al5,
  al6,
  al7,
  al8,
  al9,
  round((select avg(x) from unnest(array[ct1, ct2, ct3, ct4, ct5, ct6, ct8, ct9]) as x)::numeric, 3) as ct_mean,
  round((select avg(x) from unnest(array[sc1, sc2, sc3, sc4, sc5, sc6, sc7, sc8, sc9]) as x)::numeric, 3) as sc_mean,
  round((select avg(x) from unnest(array[hc1, hc2, hc3, hc4, hc5, (6 - hc6)]) as x)::numeric, 3) as hc_mean,
  round((select avg(x) from unnest(array[ase1, ase2, ase3, ase4, gse1, gse2, gse3, gse4]) as x)::numeric, 3) as se_mean,
  round((select avg(x) from unnest(array[gd1, gd2, gd3, gd4, gd5, gd6, gd8]) as x)::numeric, 3) as gd_mean,
  round((select avg(x) from unnest(array[co1, co2, co3, co4, co5, co6]) as x)::numeric, 3) as co_mean,
  round((select avg(x) from unnest(array[al1, al2, al3, al4, al5, al6, al7, al8, al9]) as x)::numeric, 3) as al_mean
from public.responses;

revoke all on public.responses_spss from anon, authenticated;
revoke all on public.responses_spss from service_role;   -- export in the SQL Editor; not exposed to the server
-- ---------- Analysis exports (named exactly like the form codes) ----------
-- export_spss: every variable + Case_ID + screening flags (Valid = 1 → include).
-- export_smartpls: valid cases only, numeric indicators/controls only, missing = -99.
-- Export: SQL Editor → select * from export_spss;  (or export_smartpls) → Download CSV.
drop view if exists public.export_spss;
create view public.export_spss
with (security_invoker = true) as
with base as (
  select r.*,
    exists (select 1 from public.withdrawals w where w.receipt_code = r.receipt_code) as withdrawn,
    -- repeat submissions are counted among real (non-test) submissions only
    row_number() over (partition by coalesce(r.respondent_id::text, r.id::text), (coalesce(r.src, '') = 'test') order by r.created_at) as device_seq,
    ((case when (select count(x) from unnest(array[ct1, ct2, ct3, ct4, ct5, ct6, ct8, ct9]) as x) >= 3 and (select count(distinct x) from unnest(array[ct1, ct2, ct3, ct4, ct5, ct6, ct8, ct9]) as x) = 1 then 1 else 0 end)
     + (case when (select count(x) from unnest(array[sc1, sc2, sc3, sc4, sc5, sc6, sc7, sc8, sc9]) as x) >= 3 and (select count(distinct x) from unnest(array[sc1, sc2, sc3, sc4, sc5, sc6, sc7, sc8, sc9]) as x) = 1 then 1 else 0 end)
     + (case when (select count(x) from unnest(array[hc1, hc2, hc3, hc4, hc5, hc6]) as x) >= 3 and (select count(distinct x) from unnest(array[hc1, hc2, hc3, hc4, hc5, hc6]) as x) = 1 then 1 else 0 end)
     + (case when (select count(x) from unnest(array[ase1, ase2, ase3, ase4, gse1, gse2, gse3, gse4]) as x) >= 3 and (select count(distinct x) from unnest(array[ase1, ase2, ase3, ase4, gse1, gse2, gse3, gse4]) as x) = 1 then 1 else 0 end)
     + (case when (select count(x) from unnest(array[gd1, gd2, gd3, gd4, gd5, gd6, gd8]) as x) >= 3 and (select count(distinct x) from unnest(array[gd1, gd2, gd3, gd4, gd5, gd6, gd8]) as x) = 1 then 1 else 0 end)
     + (case when (select count(x) from unnest(array[co1, co2, co3, co4, co5, co6]) as x) >= 3 and (select count(distinct x) from unnest(array[co1, co2, co3, co4, co5, co6]) as x) = 1 then 1 else 0 end)
     + (case when (select count(x) from unnest(array[al1, al2, al3, al4, al5, al6, al7, al8, al9]) as x) >= 3 and (select count(distinct x) from unnest(array[al1, al2, al3, al4, al5, al6, al7, al8, al9]) as x) = 1 then 1 else 0 end)) as straightline_n
  from public.responses r
)
select
  id as "Case_ID",
  receipt_code as "Receipt",
  created_at as "Submitted_at",
  started_at as "Started_at",
  duration_sec as "Duration_sec",
  form_version as "Form_version",
  ui_lang as "Language",
  device_type as "Device",
  src as "Source",
  bot_check as "Bot_check",
  (case when coalesce(src, '') = 'test' then 1 else 0 end) as "Flag_test",
  (case when withdrawn then 1 else 0 end) as "Flag_withdrawn",
  (case when coalesce(attention_pass, false) then 0 else 1 end) as "Flag_attention",
  (case when coalesce(duration_sec, 0) < 300 then 1 else 0 end) as "Flag_too_fast",
  (case when device_seq > 1 then 1 else 0 end) as "Flag_repeat_device",
  straightline_n as "Flag_straightline_n",
  (case when (coalesce(src, '') <> 'test' and not withdrawn and coalesce(attention_pass, false)
     and coalesce(duration_sec, 0) >= 300 and device_seq = 1) then 1 else 0 end) as "Valid",
  dem1 as "DEM1",
  dem2 as "DEM2",
  dem3 as "DEM3",
  dem4 as "DEM4",
  dem5 as "DEM5",
  dem6 as "DEM6",
  dem6_other as "DEM6_other",
  dem7 as "DEM7",
  dem8 as "DEM8",
  dem9 as "DEM9",
  dem10 as "DEM10",
  (case when 'chatgpt' = any(use1) then 1 else 0 end) as "USE1_chatgpt",
  (case when 'gemini' = any(use1) then 1 else 0 end) as "USE1_gemini",
  (case when 'copilot' = any(use1) then 1 else 0 end) as "USE1_copilot",
  (case when 'meta_ai' = any(use1) then 1 else 0 end) as "USE1_meta_ai",
  (case when 'claude' = any(use1) then 1 else 0 end) as "USE1_claude",
  (case when 'deepseek' = any(use1) then 1 else 0 end) as "USE1_deepseek",
  (case when 'perplexity' = any(use1) then 1 else 0 end) as "USE1_perplexity",
  (case when 'github_copilot' = any(use1) then 1 else 0 end) as "USE1_github_copilot",
  (case when 'grammarly_quillbot' = any(use1) then 1 else 0 end) as "USE1_grammarly_quillbot",
  (case when 'other' = any(use1) then 1 else 0 end) as "USE1_other_selected",
  use1_other as "USE1_other",
  use2 as "USE2",
  use3 as "USE3",
  use4 as "USE4",
  (case when 'concepts' = any(use5) then 1 else 0 end) as "USE5_concepts",
  (case when 'writing' = any(use5) then 1 else 0 end) as "USE5_writing",
  (case when 'coding' = any(use5) then 1 else 0 end) as "USE5_coding",
  (case when 'maths' = any(use5) then 1 else 0 end) as "USE5_maths",
  (case when 'summarising' = any(use5) then 1 else 0 end) as "USE5_summarising",
  (case when 'exam_prep' = any(use5) then 1 else 0 end) as "USE5_exam_prep",
  (case when 'ideas' = any(use5) then 1 else 0 end) as "USE5_ideas",
  (case when 'feedback' = any(use5) then 1 else 0 end) as "USE5_feedback",
  (case when 'translation' = any(use5) then 1 else 0 end) as "USE5_translation",
  (case when 'research_sources' = any(use5) then 1 else 0 end) as "USE5_research_sources",
  (case when 'other' = any(use5) then 1 else 0 end) as "USE5_other_selected",
  use5_other as "USE5_other",
  use6 as "USE6",
  use8 as "USE8",
  use9 as "USE9",
  (case when 'info' = any(use10) then 1 else 0 end) as "USE10_info",
  (case when 'messages' = any(use10) then 1 else 0 end) as "USE10_messages",
  (case when 'entertainment' = any(use10) then 1 else 0 end) as "USE10_entertainment",
  (case when 'advice' = any(use10) then 1 else 0 end) as "USE10_advice",
  (case when 'planning' = any(use10) then 1 else 0 end) as "USE10_planning",
  (case when 'skills' = any(use10) then 1 else 0 end) as "USE10_skills",
  (case when 'work' = any(use10) then 1 else 0 end) as "USE10_work",
  (case when 'none' = any(use10) then 1 else 0 end) as "USE10_none",
  (case when 'other' = any(use10) then 1 else 0 end) as "USE10_other_selected",
  use10_other as "USE10_other",
  ct1 as "CT1",
  ct2 as "CT2",
  ct3 as "CT3",
  ct4 as "CT4",
  att as "ATT",
  ct5 as "CT5",
  ct6 as "CT6",
  ct8 as "CT8",
  ct9 as "CT9",
  sc1 as "SC1",
  sc2 as "SC2",
  sc3 as "SC3",
  sc4 as "SC4",
  sc5 as "SC5",
  sc6 as "SC6",
  sc7 as "SC7",
  sc8 as "SC8",
  sc9 as "SC9",
  hc1 as "HC1",
  hc2 as "HC2",
  hc3 as "HC3",
  hc4 as "HC4",
  hc5 as "HC5",
  hc6 as "HC6",
  (6 - hc6) as "HC6_R",
  ase1 as "ASE1",
  ase2 as "ASE2",
  ase3 as "ASE3",
  ase4 as "ASE4",
  gse1 as "GSE1",
  gse2 as "GSE2",
  att2 as "ATT2",
  gse3 as "GSE3",
  gse4 as "GSE4",
  gd1 as "GD1",
  gd2 as "GD2",
  gd3 as "GD3",
  gd4 as "GD4",
  gd5 as "GD5",
  gd6 as "GD6",
  gd8 as "GD8",
  co1 as "CO1",
  co2 as "CO2",
  co3 as "CO3",
  co4 as "CO4",
  co5 as "CO5",
  co6 as "CO6",
  al1 as "AL1",
  al2 as "AL2",
  al3 as "AL3",
  al4 as "AL4",
  al5 as "AL5",
  al6 as "AL6",
  al7 as "AL7",
  al8 as "AL8",
  al9 as "AL9",
  round((select avg(x) from unnest(array[ct1, ct2, ct3, ct4, ct5, ct6, ct8, ct9]) as x)::numeric, 3) as "CT_mean",
  round((select avg(x) from unnest(array[sc1, sc2, sc3, sc4, sc5, sc6, sc7, sc8, sc9]) as x)::numeric, 3) as "SC_mean",
  round((select avg(x) from unnest(array[hc1, hc2, hc3, hc4, hc5, (6 - hc6)]) as x)::numeric, 3) as "HC_mean",
  round((select avg(x) from unnest(array[ase1, ase2, ase3, ase4, gse1, gse2, gse3, gse4]) as x)::numeric, 3) as "SE_mean",
  round((select avg(x) from unnest(array[gd1, gd2, gd3, gd4, gd5, gd6, gd8]) as x)::numeric, 3) as "GD_mean",
  round((select avg(x) from unnest(array[co1, co2, co3, co4, co5, co6]) as x)::numeric, 3) as "CO_mean",
  round((select avg(x) from unnest(array[al1, al2, al3, al4, al5, al6, al7, al8, al9]) as x)::numeric, 3) as "AL_mean"
from base
order by id;

drop view if exists public.export_smartpls;
create view public.export_smartpls
with (security_invoker = true) as
with base as (
  select r.*,
    exists (select 1 from public.withdrawals w where w.receipt_code = r.receipt_code) as withdrawn,
    -- repeat submissions are counted among real (non-test) submissions only
    row_number() over (partition by coalesce(r.respondent_id::text, r.id::text), (coalesce(r.src, '') = 'test') order by r.created_at) as device_seq
  from public.responses r
)
select
  id as "Case_ID",
  coalesce(dem1, -99) as "DEM1",
  coalesce(dem2, -99) as "DEM2",
  coalesce(dem4, -99) as "DEM4",
  coalesce(dem6, -99) as "DEM6",
  coalesce(dem7, -99) as "DEM7",
  coalesce(dem8, -99) as "DEM8",
  coalesce(dem9, -99) as "DEM9",
  coalesce(dem10, -99) as "DEM10",
  coalesce(use2, -99) as "USE2",
  coalesce(use3, -99) as "USE3",
  coalesce(use4, -99) as "USE4",
  coalesce(use6, -99) as "USE6",
  coalesce(use8, -99) as "USE8",
  coalesce(use9, -99) as "USE9",
  coalesce(ct1, -99) as "CT1",
  coalesce(ct2, -99) as "CT2",
  coalesce(ct3, -99) as "CT3",
  coalesce(ct4, -99) as "CT4",
  coalesce(ct5, -99) as "CT5",
  coalesce(ct6, -99) as "CT6",
  coalesce(ct8, -99) as "CT8",
  coalesce(ct9, -99) as "CT9",
  coalesce(sc1, -99) as "SC1",
  coalesce(sc2, -99) as "SC2",
  coalesce(sc3, -99) as "SC3",
  coalesce(sc4, -99) as "SC4",
  coalesce(sc5, -99) as "SC5",
  coalesce(sc6, -99) as "SC6",
  coalesce(sc7, -99) as "SC7",
  coalesce(sc8, -99) as "SC8",
  coalesce(sc9, -99) as "SC9",
  coalesce(hc1, -99) as "HC1",
  coalesce(hc2, -99) as "HC2",
  coalesce(hc3, -99) as "HC3",
  coalesce(hc4, -99) as "HC4",
  coalesce(hc5, -99) as "HC5",
  coalesce(6 - hc6, -99) as "HC6_R",
  coalesce(ase1, -99) as "ASE1",
  coalesce(ase2, -99) as "ASE2",
  coalesce(ase3, -99) as "ASE3",
  coalesce(ase4, -99) as "ASE4",
  coalesce(gse1, -99) as "GSE1",
  coalesce(gse2, -99) as "GSE2",
  coalesce(gse3, -99) as "GSE3",
  coalesce(gse4, -99) as "GSE4",
  coalesce(gd1, -99) as "GD1",
  coalesce(gd2, -99) as "GD2",
  coalesce(gd3, -99) as "GD3",
  coalesce(gd4, -99) as "GD4",
  coalesce(gd5, -99) as "GD5",
  coalesce(gd6, -99) as "GD6",
  coalesce(gd8, -99) as "GD8",
  coalesce(co1, -99) as "CO1",
  coalesce(co2, -99) as "CO2",
  coalesce(co3, -99) as "CO3",
  coalesce(co4, -99) as "CO4",
  coalesce(co5, -99) as "CO5",
  coalesce(co6, -99) as "CO6",
  coalesce(al1, -99) as "AL1",
  coalesce(al2, -99) as "AL2",
  coalesce(al3, -99) as "AL3",
  coalesce(al4, -99) as "AL4",
  coalesce(al5, -99) as "AL5",
  coalesce(al6, -99) as "AL6",
  coalesce(al7, -99) as "AL7",
  coalesce(al8, -99) as "AL8",
  coalesce(al9, -99) as "AL9"
from base
where (coalesce(src, '') <> 'test' and not withdrawn and coalesce(attention_pass, false)
     and coalesce(duration_sec, 0) >= 300 and device_seq = 1)
order by id;

revoke all on public.export_spss from anon, authenticated, service_role;
revoke all on public.export_smartpls from anon, authenticated, service_role;

notify pgrst, 'reload schema';   -- let the API see the new tables immediately
